/** 把后端返回的站内相对地址（/zhi2-dev/... 、 upload/xxx.jpg 等）解析为浏览器可访问的 URL。 */
export function resolveAssetUrl(input?: string): string {
  if (!input) return ''
  const s = String(input).trim()
  if (!s) return ''
  // data/blob/已带协议或协议相对的地址原样返回
  if (/^(data:|blob:)/i.test(s) || /^(https?:)?\/\//i.test(s)) return s
  if (isServerMediaStoragePath(s)) {
    if (PROXY_TARGET) {
      const path = s.startsWith('/') ? s : `/${s}`
      try { return new URL(path, PROXY_TARGET).href } catch { /* fallthrough */ }
    }
    return resolveServerMediaUrl(s)
  }
  // 绝对路径（/ 开头）
  if (s.startsWith('/')) {
    // H5：优先用代理目标补齐为完整 URL；无代理目标时用相对路径（走同源/开发代理）
    if (PROXY_TARGET) {
      try { return new URL(s, PROXY_TARGET).href } catch { return s }
    }
    return s
  }
  // 相对路径（如 upload/xxx.jpg、static/xxx.png）：补全为可访问地址
  // H5：加前导 / 走同源/开发代理
  if (PROXY_TARGET) {
    try { return new URL(`/${s}`, PROXY_TARGET).href } catch { /* fallthrough */ }
  }
  return `/${s}`
}

