/**
 * 把后端返回的站内地址解析为浏览器可访问的 URL。
 * 本项目全为 H5：站内资源统一返回以 / 开头的根相对路径，由当前站点 nginx 反代解析，
 * PC/手机同源一致。绝不拼死 test 内网域名——否则手机外网不可达（PC 内网可见、手机不可见）。
 */
export function resolveAssetUrl(input?: string): string {
  if (!input) return ''
  const s = String(input).trim()
  if (!s) return ''
  // data/blob/已带协议或协议相对的地址原样返回（外部图床、完整 URL 不变）
  if (/^(data:|blob:)/i.test(s) || /^(https?:)?\/\//i.test(s)) return s
  // 站内路径（/zhi2-pro/... 、 upload/xxx.jpg 等）：统一归一化到根相对路径交给同源反代
  return s.startsWith('/') ? s : `/${s}`
