/** resolveAssetUrl：站内路径统一返回根相对路径（同源反代），不拼 test 内网域名 */
test('resolveAssetUrl 站内路径归一为根相对路径，完整 URL/data/blob 原样返回', () => {
  expect(resolveAssetUrl('/zhi2-pro/2026/a.png')).toBe('/zhi2-pro/2026/a.png')
  expect(resolveAssetUrl('zhi2-dev/2026/a.png')).toBe('/zhi2-dev/2026/a.png')
  expect(resolveAssetUrl('upload/b.png')).toBe('/upload/b.png')
  expect(resolveAssetUrl('https://szfweb.szzfcjj.cn:8887/zhi2-pro/a.png')).toBe('https://szfweb.szzfcjj.cn:8887/zhi2-pro/a.png')
  expect(resolveAssetUrl('//cdn.example.com/a.png')).toBe('//cdn.example.com/a.png')
  expect(resolveAssetUrl('data:image/png;base64,AAAA')).toBe('data:image/png;base64,AAAA')
  expect(resolveAssetUrl('blob:http://x/abc')).toBe('blob:http://x/abc')
  expect(resolveAssetUrl('')).toBe('')
})

